//! The command-line tree of `amh`: every group, action, option, and help text.
// 🧑 "Consolidate the manager helpers. Make them into one command `amh` ... Make the subcommands nested and with sane names ... anyone can start from the root --help page and work their way naturally"
// 🧑 "Don't keep calling the old helper commands. Integrate them into a single program. Later we will rewrite it in Rust."

use clap::{Arg, ArgAction, Command};

/// Build the whole command tree.
pub fn command() -> Command {
    Command::new("amh").about("Agent manager helper: one command for agents and managers.\n\nStart at `amh --help` and follow the groups down; every level has its own `--help`.").subcommand_required(true).arg_required_else_help(true)
        .arg(Arg::new("task_file").long("task-file").global(true).value_name("NAME.md").help("your task file; accepted before or after subcommands"))
        // 🧑 "there needs to be sane short commands for common tasks like spawning agents, without needing tons of flags"
    .subcommand(Command::new("new").about("The human: start an agent on a new task, in the directory you are in.").long_about("The human: start an agent on a new task, in the directory you are in.\n\nIt runs Claude at the default model and effort and reports to the main manager. Without GOAL your editor opens for it.")
        .arg(Arg::new("task").required(true).value_name("NAME").help("the new task's name; also its tag in email subjects"))
        .arg(Arg::new("goal").required(false).value_name("GOAL").help("what the agent is to do"))
        .arg(Arg::new("as_manager").short('m').long("manager").action(ArgAction::SetTrue).help("the new agent is a manager"))
        .arg(Arg::new("tool").short('t').long("tool").value_name("TOOL").value_parser(["claude", "codex", "cursor", "antigravity"]).help("default: claude"))
    )
    .subcommand(Command::new("ls").about("The human: the tree of running agents with their open items."))
    .subcommand(Command::new("view").about("The human: open an agent's live terminal; detach to leave it running.")
        .arg(Arg::new("who").required(true).value_name("NAME"))
        .arg(Arg::new("read_only").short('r').long("read-only").action(ArgAction::SetTrue).help("only watch"))
    )
    .subcommand(Command::new("say").about("The human: send an agent a request from you.").long_about("The human: send an agent a request from you.\n\nIt reaches the agent within seconds, exactly like an email from you. Without TEXT your editor opens.")
        .arg(Arg::new("task").required(true).value_name("NAME"))
        .arg(Arg::new("text").required(false).value_name("TEXT"))
    )
    .subcommand(Command::new("human").about("The human: note an item for yourself under `human pending`, list them, or drop one.").long_about("The human: note an item for yourself under `human pending`, list them, or drop one.\n\n  amh human 'Review the VL draft'\n  amh human\n  amh human --done 'Review the VL draft'\n\nThe item is a bullet in the task list `TODO.md`; no agent is started and nothing is sent. Without TEXT your items are listed.")
        .arg(Arg::new("text").required(false).value_name("TEXT"))
        .arg(Arg::new("done").long("done").action(clap::ArgAction::SetTrue).requires("text").help("drop the item TEXT instead of adding it"))
    )
    .subcommand(Command::new("edit").about("The human: open a task file in your editor; what you add at the end goes to its agent.")
        .arg(Arg::new("task").required(true).value_name("NAME"))
    )
    .subcommand(Command::new("stop").about("The human: close a task and stop its agent, even with open items, after asking you once.")
        .arg(Arg::new("task").required(true).value_name("NAME"))
    )
    .subcommand(Command::new("log").about("The human: what amh did for a task: mail in, deliveries, problems, and the agent's amh commands.")
        .arg(Arg::new("task").required(true).value_name("NAME"))
        .arg(Arg::new("lines").short('n').long("lines").value_name("N").help("how many of the newest lines; default 60"))
    )
    .subcommand(Command::new("tell").about("Send a message to your manager, the human, an agent you manage, or the guest.").subcommand_required(true).arg_required_else_help(true)
            .subcommand(Command::new("manager").about("Message your manager, like a chat message.").long_about("Message your manager, like a chat message.\n\nUse it only to ask for help or coordination, or to say you are done or blocked.\nAt most 600 characters. For details, write a file and name its path in the message.")
                .arg(Arg::new("text").value_name("TEXT").conflicts_with("file").help("message; omit to read standard input"))
                .arg(Arg::new("file").long("file").help("file holding the message"))
                .arg(Arg::new("blocked").long("blocked").action(ArgAction::SetTrue).help("you cannot continue without the manager").conflicts_with("done"))
                .arg(Arg::new("done").long("done").action(ArgAction::SetTrue).help("your task is finished").conflicts_with("blocked"))
            )
            .subcommand(Command::new("human").about("Message the human through the configured transport.").long_about("Message the human through the configured transport.\n\nWith human.transport=zulip, sends a private Zulip bot message; otherwise sends email.\nThe body comes from TEXT, --file, or standard input. Batch the acknowledgement, answer, and item changes (--add, --done) in one call.\nThe task tag is added for you. Zulip Message-IDs are zulip:ID; pass --replaces zulip:ID to delete your earlier bot message after its replacement is sent. Uploaded attachments appear as links.\nFor email, --replaces MESSAGE_ID trashes the earlier message if unread; `amh mail unread` lists them.")
                .arg(Arg::new("task_file").long("task-file").value_name("NAME.md").help("your task file, when `amh` cannot tell who you are"))
                .arg(Arg::new("subject").long("subject").required(true).help("plain English; a new subject must be under 60 characters, a reply reuses the subject of its thread"))
                .arg(Arg::new("report_label").long("report-label").value_parser(crate::mail::REPORT_LABELS).help("stock_news_watch only: display label/topic; replies retain the actual task owner"))
                .arg(Arg::new("email").long("email").action(ArgAction::SetTrue).help("send this one message by email even when human.transport=zulip; Markdown links `[label](url)` show as the label"))
                .arg(Arg::new("text").value_name("TEXT").conflicts_with("file").help("message body; omit to read standard input"))
                .arg(Arg::new("file").long("file").help("file holding the message body"))
                .arg(Arg::new("add").long("add").action(ArgAction::Append).value_name("ITEM").help("also record ITEM, in the human's words, as their new request on your open items; it is listed in this email; repeat as needed"))
                .arg(Arg::new("done").long("done").action(ArgAction::Append).value_name("ITEM").help("also remove the finished ITEM from your open items; copy its text from `amh todo list`, with or without the leading 🧑 mark; it is listed in this email; repeat as needed"))
                .arg(Arg::new("attach").long("attach").action(ArgAction::Append).value_name("PATH").help("a file to attach, such as a figure the human asked to see; repeat as needed; 20 MB in total at most"))
                .arg(Arg::new("replaces").long("replaces").action(ArgAction::Append).value_name("MESSAGE_ID").help("an earlier email of yours that this one replaces; if the human has not read it, it goes to the trash; repeat as needed"))
            )
            .subcommand(Command::new("agent").about("Message an agent you manage.").long_about("Message an agent you manage.\n\nThe sender is your Omnigent session, or the runat address of --task-file TASK (also OMO_AGENT_TASK_FILE) when the session identity is unavailable. A script that is no agent passes --from NAME.")
                .arg(Arg::new("who").required(true).value_name("WHO").help("its task file name, or its address"))
                .arg(Arg::new("text").required(false).value_name("TEXT").help("message; omit to read standard input"))
                .arg(Arg::new("file").long("file").help("file holding the message, instead of TEXT"))
                .arg(Arg::new("from").long("from").value_name("NAME").help("only for a script that is no agent, e.g. a cron job: its name, shown to the agent as the sender"))
            )
            .subcommand(Command::new("guest").about("The guest agent only: answer a guest email; it goes to the guest alone.")
                .arg(Arg::new("mail").long("mail").required(true).value_name("FILE.txt").help("name of the stored guest email being answered"))
                .arg(Arg::new("file").long("file").required(true).help("file holding the answer"))
                .arg(Arg::new("image").long("image").action(ArgAction::Append).value_name("PATH").help("png, jpeg, gif, or webp image to attach; repeat as needed"))
            )
        )
        .subcommand(Command::new("todo").about("Read and update your own list of open work.").subcommand_required(true).arg_required_else_help(true)
            .subcommand(Command::new("list").about("Show your open requests with IDs, stages, and dependencies.")
                .arg(Arg::new("task_file").long("task-file").value_name("NAME.md").help("your task file, when `amh` cannot tell who you are"))
            )
            .subcommand(Command::new("add").about("Add open items.").long_about("Add open items.\n\nAdding the human's requests emails the human at once, one email per call: give every new item in the same call. To send them together with a message of yours, use `amh tell human --add ITEM` instead.")
                .arg(Arg::new("task_file").long("task-file").value_name("NAME.md").help("your task file, when `amh` cannot tell who you are"))
                .arg(Arg::new("item").action(ArgAction::Append).num_args(1..).required(true).value_name("ITEM").help("one item per argument"))
                .arg(Arg::new("from_human").long("from-human").action(ArgAction::SetTrue).help("the items are the human's requests, in the human's words"))
            )
            .subcommand(Command::new("done").about("Resolve human requests or request their creator's approval.").long_about("Resolve human requests or request their creator's approval.\n\nHuman requests resolve immediately and email the human at once, one email per call: give every finished item in the same call. To send them together with a message of yours, use `amh tell human --done ITEM` instead. When the human wrote that they want no notice, add --quiet-because with their words.\nAgent requests stay open at `resolution requested` until their creator approves or rejects them. Give request IDs or exact item texts from `amh todo list`. Dependencies must resolve first.\nRemoving the last item does not stop an agent; when the whole ordinary task is complete, run `amh task close TASK.md` last. Standing roles remain open.")
                .arg(Arg::new("task_file").long("task-file").value_name("NAME.md").help("your task file, when `amh` cannot tell who you are"))
                .arg(Arg::new("item").action(ArgAction::Append).num_args(1..).required(true).value_name("ITEM").help("request ID or exact item text (without ID/stage), with or without the leading 🧑 mark; one item per argument"))
                .arg(Arg::new("evidence").long("evidence").required(true).help("one sentence saying how you know they are finished, or why they were cancelled"))
                .arg(Arg::new("quiet_because").long("quiet-because").value_name("WORDS").help("remove without emailing the human: only when the human wrote that they want no notice; give their own words, which are noted in the task file"))
            )
            .subcommand(Command::new("replace").about("Reword one open item.")
                .arg(Arg::new("task_file").long("task-file").value_name("NAME.md").help("your task file, when `amh` cannot tell who you are"))
                .arg(Arg::new("old").required(true).value_name("OLD"))
                .arg(Arg::new("new").required(true).value_name("NEW"))
            )
            .subcommand(Command::new("approve").about("Approve resolution of a request you created; before its owner asked for that, this withdraws the request.")
                .arg(Arg::new("id").required(true).value_name("ID"))
                .arg(Arg::new("task_file").long("task-file").value_name("NAME.md").help("your task file, when amh cannot tell who you are"))
            )
            .subcommand(Command::new("reject").about("Return a request you created to its owner for more work.")
                .arg(Arg::new("id").required(true).value_name("ID"))
                .arg(Arg::new("reason").long("reason").required(true).value_name("REASON"))
                .arg(Arg::new("task_file").long("task-file").value_name("NAME.md").help("your task file, when amh cannot tell who you are"))
            )
            .subcommand(Command::new("wait").about("Make one of your requests wait for other requests to resolve.").long_about("Make one of your requests wait for other requests to resolve, or for something outside amh.\n\nUse the IDs shown by `amh todo list`; repeat --for for several blockers. Its owner is notified when all blockers resolve. For an outside event use --on WHAT, e.g. `amh todo wait ID --on 'human_mgr.md calling amh mail done'`; it stays until you run `amh todo wait ID --clear-on`. A waiting request is not reminded about; your other ready requests still are.")
                .arg(Arg::new("id").required(true).value_name("ID"))
                .arg(Arg::new("blocker").long("for").action(ArgAction::Append).value_name("ID").required_unless_present_any(["on", "clear_on"]))
                .arg(Arg::new("on").long("on").value_name("WHAT").value_parser(clap::builder::NonEmptyStringValueParser::new()).conflicts_with("clear_on").help("wait for something outside amh, e.g. 'human_mgr.md calling amh mail done'; only you clear it, with --clear-on"))
                .arg(Arg::new("clear_on").long("clear-on").action(ArgAction::SetTrue).help("drop the --on wait; request dependencies stay"))
                .arg(Arg::new("task_file").long("task-file").value_name("NAME.md").help("your task file, when amh cannot tell who you are"))
            )
            .subcommand(Command::new("take").about("Take ownership of a request transferred to your task.")
                .arg(Arg::new("id").required(true).value_name("ID"))
                .arg(Arg::new("task_file").long("task-file").value_name("NAME.md").help("your task file, when amh cannot tell who you are"))
            )
        )
        .subcommand(Command::new("task").about("Managers: create, inspect, and close the tasks of agents you manage. Any agent: close yourself.").long_about("Managers: create, inspect, and close the tasks of agents you manage. Any agent: close yourself.\n\nA task is named by its file name, with or without `.md`, or by a path to the file.\nWhen a task must wait, set it with `status TASK blocked --on WHAT`, where WHAT is the thing it waits for, never just who: `--on 'human reviewing docs/plan.md'`, not `--on human`.").subcommand_required(true).arg_required_else_help(true)
            .subcommand(Command::new("start").about("Create or restart a task with a fresh agent.").long_about("Create or restart a task with a fresh agent.\n\nAn existing task whose agent failed or stopped can be restarted on another tool:\n  amh task start TASK.md --tool codex --dir DIR --prompt FILE\nThe task file, history, and open items are kept. Running, idle, and waiting agents must first be stopped with `amh agent stop TASK.md`. Pass --manager ADDRESS to keep the original manager when someone else restarts the task.\n\nPrints the new agent's address. The agent gets the standing instructions, then your prompt, then the quoted human email lines.")
                .arg(Arg::new("task").required(true).value_name("TASK.md").help("new or existing task file name; also the agent's tag in email subjects"))
                .arg(Arg::new("dir").long("dir").required(true).help("directory the agent works in"))
                .arg(Arg::new("prompt").long("prompt").required(true).value_name("FILE").help("file holding the goal: one goal line, then sub-goals as bullets"))
                .arg(Arg::new("tool").long("tool").value_parser(["claude", "codex", "cursor", "antigravity"]).help("default: claude for managers, codex for workers"))
                .arg(Arg::new("model").long("model").help("default: the tool's usual model"))
                .arg(Arg::new("effort").long("effort").help("reasoning effort; default: the tool's usual effort"))
                .arg(Arg::new("manager").long("manager").value_name("ADDRESS").help("who the agent reports to; default: you"))
                .arg(Arg::new("as_manager").long("as-manager").action(ArgAction::SetTrue).help("the new agent is itself a manager"))
                .arg(Arg::new("email").long("email").value_name("FILE").help("stored human email that caused this task; needs --lines"))
                .arg(Arg::new("lines").long("lines").value_name("START-END").help("the relevant lines of --email"))
            )
            .subcommand(Command::new("show").about("Show tasks' status, agent address, and open items.")
                .arg(Arg::new("task").action(ArgAction::Append).num_args(1..).required(true).value_name("TASK.md"))
            )
            .subcommand(Command::new("close").about("Mark a task done, stop its agent, and move it to `previous` in the task list.").long_about("Mark a task done, stop its agent, and move it to `previous` in the task list.\n\nWithout TASK.md, an agent closes itself: its own task, then its own session.\nClosing your own session can terminate this command with exit 137 after the task has been saved as closed. A manager can verify it with `amh task show TASK`.\nRefuses while the task has open items. Emails the human one line saying the task is closed.")
                .arg(Arg::new("task_file").long("task-file").value_name("NAME.md").help("your task file, when `amh` cannot tell who you are"))
                .arg(Arg::new("task").required(false).value_name("TASK.md").help("the task to close; omit to close yourself"))
                .arg(Arg::new("agent_gone").long("agent-gone").action(ArgAction::SetTrue).help("close even though the agent cannot be stopped because it no longer exists"))
                .arg(Arg::new("no_email").long("no-email").action(ArgAction::SetTrue).help("do not email the human; for test tasks only"))
            )
            .subcommand(Command::new("status").about("Set a task's status; a blocked task says what it waits for.").long_about("Set a task's status; a blocked task says what it waits for.\n\n`blocked` needs --on WHAT. WHAT is the thing the task waits for, never just who:\n  amh task status TASK blocked --on 'human reviewing docs/plan.md'\n  amh task status TASK blocked --on 'human answering the 3 questions in my email of Oct 5 14:02'\n  amh task status TASK blocked --on other_task.md\nNot `--on human`: that says who, and nobody can tell what is being waited for. Start WHAT with `human` when the human must act.")
                .arg(Arg::new("task").required(true).value_name("TASK.md"))
                .arg(Arg::new("status").required(true).value_parser(["running", "long_running", "blocked"]))
                .arg(Arg::new("on").long("on").value_name("WHAT").value_parser(clap::builder::NonEmptyStringValueParser::new()).help("the thing a blocked task waits for, never just who: e.g. `human reviewing docs/plan.md`, `human answering the 3 questions in my email of Oct 5 14:02`, or another task file such as `other_task.md`; start it with `human` when the human must act"))
            )
            .subcommand(Command::new("place").about("Pin a task's row under a section of the task list, whatever its status.").long_about("Pin a task's row under a section of the task list, whatever its status.\n\nFor when the human says where a task goes, e.g. a finished task kept under `low priority`:\n  amh task place TASK --under 'low priority'\nThe row stays there until the task's status changes or you run it with --under auto, which puts the row back where the status says.")
                .arg(Arg::new("task").required(true).value_name("TASK.md"))
                .arg(Arg::new("under").long("under").required(true).value_name("SECTION").help("current, 'human pending', 'low priority', previous, or auto"))
            )
            .subcommand(Command::new("role").about("Record whether a task is a manager or a worker; nothing else about it changes and its agent keeps running.").long_about("Record whether a task is a manager or a worker; nothing else about it changes and its agent keeps running.\n\nFor correcting a task whose recorded role does not match what it does, e.g.\n  amh task role pb_support.md manager\nThe agent reads its new role from its guides the next time it is started or replaced.")
                .arg(Arg::new("task").required(true).value_name("TASK.md"))
                .arg(Arg::new("role").required(true).value_parser(["manager", "worker"]).value_name("ROLE"))
            )
            .subcommand(Command::new("adopt").about("A manager: make a task report to you instead of its recorded manager; its agent keeps running.")
                .arg(Arg::new("task").required(true).value_name("TASK.md"))
            )
            .subcommand(Command::new("edit").about("The human: open a task file in your editor; what you add at the end goes to its agent as your request.").long_about("The human: open a task file in your editor; what you add at the end goes to its agent as your request.\n\nWorks like `crontab -e`: you edit a copy, and on close the text you added at the end is delivered to the task's agent as if you had emailed it. Changing anything else is refused, and you are offered to reopen the copy. The editor is $VISUAL, else $EDITOR, else vi.")
                .arg(Arg::new("task").required(true).value_name("TASK.md"))
            )
            .subcommand(Command::new("list-remove").about("Remove an entry that `list-add` put in the task list.").long_about("Remove an entry that `list-add` put in the task list.\n\n  amh task list-remove 'Exxact server access below the OS'\n\nTEXT is the entry without its bullet. Rows of tasks are not touched; close a task with `amh task close`.")
                .arg(Arg::new("entry").required(true).value_name("TEXT"))
            )
            .subcommand(Command::new("list-add").about("List an entry without creating a task file or agent.").long_about("List an entry without creating a task file or agent.\n\n  amh task list-add 'Exxact server access below the OS' --under 'low priority'\n\nSaves a plain bullet in the database-backed TODO.md export. Repeating an entry moves it to the requested section without duplicating it. Direct edits to TODO.md are overwritten.")
                .arg(Arg::new("entry").required(true).value_name("TEXT"))
                .arg(Arg::new("under").long("under").required(true).value_parser(["current", "human pending", "low priority", "previous"]).value_name("SECTION"))
            )
            .subcommand(Command::new("note").about("Append a manager note to a task file.")
                .arg(Arg::new("task").required(true).value_name("TASK.md"))
                .arg(Arg::new("text").required(true).value_name("TEXT"))
            )
            .subcommand(Command::new("give").about("Add open items to a task's list.").long_about("Add open items to a task's list.\n\nGiving the human's requests emails the human at once, one email per call: give every item in the same call.")
                .arg(Arg::new("task").required(true).value_name("TASK.md"))
                .arg(Arg::new("item").action(ArgAction::Append).num_args(1..).required(true).value_name("ITEM").help("one item per argument"))
                .arg(Arg::new("from_human").long("from-human").action(ArgAction::SetTrue).help("the item is the human's request, in the human's words"))
            )
            .subcommand(Command::new("move").about("Offer an open request to another task.").long_about("Offer an open request to another task.\n\nThe source remains its owner until the destination accepts with `amh todo take ID`. The destination receives the ID and the command.")
                .arg(Arg::new("source").required(true).value_name("FROM.md"))
                .arg(Arg::new("to").required(true).value_name("TO.md"))
                .arg(Arg::new("item").required(true).value_name("ITEM"))
            )
            .subcommand(Command::new("check").about("Check that task files and the task list agree.")
            )
        )
        .subcommand(Command::new("agent").about("Managers: look at and control running agents.").subcommand_required(true).arg_required_else_help(true)
            .subcommand(Command::new("problems").about("List agents that are gone, failed, or idle with open items.")
            )
            .subcommand(Command::new("list").about("List active tasks and what their agents are doing.")
            )
            .subcommand(Command::new("org").about("Show the organization as a company: the human as CEO, managers as departments, each agent's role, open-item count and state, then structural problems.")
                .arg(Arg::new("task_file").long("task-file").value_name("NAME.md").help("your task file, when `amh` cannot tell who you are"))
            )
            .subcommand(Command::new("tree").about("Show who reports to whom, with each agent's open items.")
            )
            .subcommand(Command::new("status").about("Show whether one agent is running, idle (`ready`), failed, or missing.")
                .arg(Arg::new("who").required(true).value_name("WHO").help("its task file name, or its address"))
            )
            .subcommand(Command::new("stop").about("Stop one agent without closing its task.")
                .arg(Arg::new("who").required(true).value_name("WHO").help("its task file name, or its address"))
            )
            .subcommand(Command::new("hold").about("Pause an agent on purpose: stop it and keep its messages pending until `amh agent release`.")
                .arg(Arg::new("who").required(true).value_name("WHO").help("its task file name, or its address"))
                .arg(Arg::new("reason").long("reason").required(true).value_name("WORDS").help("why, shown in its status"))
            )
            .subcommand(Command::new("release").about("End a hold: deliver pending messages again and tell the agent to resume.")
                .arg(Arg::new("who").required(true).value_name("WHO").help("its task file name, or its address"))
                .arg(Arg::new("message").value_name("MESSAGE").help("what to tell it; default: resume the work you were doing"))
            )
            .subcommand(Command::new("replace").about("Replace a task's agent with a fresh one that gets the original request, a replacement note, MESSAGE, and the open items; the old one is stopped.")
                .arg(Arg::new("who").required(true).value_name("TASK").help("the task file name"))
                .arg(Arg::new("message").value_name("MESSAGE").help("why it is replaced, given to the new agent"))
            )
            .subcommand(Command::new("retire").about("Close for good an old session an agent left, e.g. after a partial-compaction move; its history stays readable.")
                .arg(Arg::new("who").required(true).value_name("ADDRESS").help("the old session's address, omnigent://ID; never a task's current agent"))
            )
            .subcommand(
                Command::new("view")
                    .about("Open an agent's live terminal in yours; detach to leave it running.")
                    .long_about("Open an agent's live terminal in yours; detach to leave it running.\n\nYou see what the agent sees and can type to it. Detach with the tmux prefix, then `d`; inside your own tmux, press the prefix twice.\nOmnigent parks idle agents: one with no running terminal must be woken by a message first.")
                    .arg(Arg::new("who").required(true).value_name("WHO").help("its task file name, or its address"))
                    .arg(Arg::new("read_only").long("read-only").action(ArgAction::SetTrue).help("only watch; keys are not sent to the agent")),
            )
            .subcommand(Command::new("compact").about("Tell an agent to compact its context by sending it `/compact`.")
                .arg(Arg::new("who").required(true).value_name("WHO").help("its task file name, or its address"))
            )
        )
        .subcommand(Command::new("mail").about("Look at sent emails and configure inbox routing.").after_help("Incoming routes are reloaded from config.toml or env.toml every poll. Example:\n  [mail_route.alerts]\n  mailbox = \"human\"\n  from = \"notifications@github.com\"\n  subject = \"Run failed:\"\n  to = \"ci_worker.md\"\n  disposition = \"trash\"\nOptional body is another substring filter; all filters must match. Optional priority is an integer (larger wins); equal priorities use rule name order. mailbox is human or agent; disposition is keep (default), read or trash. Unmatched emails are untouched. Trash/read happens only after a durable handoff. Rules contain no service-specific code.").subcommand_required(true).arg_required_else_help(true)
            .subcommand(Command::new("recent").about("List what the human wrote recently across all tasks, oldest first; run it before compiling anything for the human.").long_about("List what the human wrote recently across all tasks, oldest first: time, task, stored file and the first line the human wrote.\n\nRead the full file for anything relevant. Covers the human's Zulip messages and emails, not routed notifications.")
                .arg(Arg::new("hours").long("hours").value_name("HOURS").default_value("24").help("how far back to look"))
            )
            .subcommand(Command::new("unread").about("List the messages your task sent through amh that the human has not read yet.").long_about("List your task's messages the human has not read yet; under Zulip, each with its full text.\n\nTo drop one, send its replacement with `amh tell human --replaces MESSAGE_ID`.")
                .arg(Arg::new("all").long("all").action(ArgAction::SetTrue).help("Zulip only: list every task's unread messages, for the task that compresses the human's inbox"))
                .arg(Arg::new("task_file").long("task-file").value_name("NAME.md").help("your task file, when `amh` cannot tell who you are"))
            )
            .subcommand(Command::new("handled").about("Say that an email of the human needs no email back, so you are not reminded to answer it.").long_about("Say that an email of the human needs no email back, so you are not reminded to answer it.\n\nOnly for an email in which the human wrote that no reply is needed. The human's words are noted in your task file.")
                .arg(Arg::new("task_file").long("task-file").value_name("NAME.md").help("your task file, when `amh` cannot tell who you are"))
                .arg(Arg::new("mail").required(true).value_name("MAIL.txt").help("the stored email's file name, as in the reminder, e.g. `manager_mail/NAME.txt`"))
                .arg(Arg::new("because").long("because").required(true).value_name("WORDS").help("the human's own words saying no email is needed"))
            )
            // 🧑 "If agents handled certain emails they should be marked read."
            .subcommand(Command::new("done").about("Mark an email routed to your task read, after you handled it.").long_about("Mark an email routed to your task read, after you handled it.\n\nOnly the task the route delivered it to may do this, or a task it forwarded the email to by naming the file in `amh tell agent`. Run it only after actually handling the email; routes keep emails unread until then.")
                .arg(Arg::new("task_file").long("task-file").value_name("NAME.md").help("your task file, when `amh` cannot tell who you are"))
                .arg(Arg::new("mail").required(true).value_name("MAIL.txt").help("the routed email's file, as in the notification, e.g. `manager_mail/routed-human-1-26558.txt`"))
            )
        )
        .subcommand(Command::new("quota").about("Quota of Claude and Codex: what is left, when it resets, and the observer service.").subcommand_required(true).arg_required_else_help(true)
            .subcommand(Command::new("status").about("Pools, accounts, projections, and the latest quota events."))
            .subcommand(Command::new("serve").about("The observer: read the proxy, keep its routing in line with the quota, redeem reset credits; run as a systemd user unit.").long_about("The observer: read the proxy's management API every 5 minutes, publish `quota-snapshot.json`, and keep the proxy's `disabled` and `priority` in line with the quota.\n\nWithout --live it only logs what it would do (shadow mode).")
                .arg(Arg::new("live").long("live").action(ArgAction::SetTrue).help("change the proxy and redeem reset credits; otherwise only log the intended actions"))
            )
        )
        .subcommand(Command::new("manager").about("Main manager: the watcher, replacing a manager, and repository checks.").subcommand_required(true).arg_required_else_help(true)
            .after_help("Storage: the first locked operation imports existing tasks and event history into amh.sqlite3 in AMH_STATE_DIR. SQLite then owns task state; Markdown is regenerated for reading. Use `amh edit TASK` to append human prompts. The watcher archives events and dated resolved requests after 30 days and commits work-log Markdown hourly. Set [archive] commit = false to disable automatic commits. Unknown legacy resolution dates start their retention window at migration.")
            .subcommand(Command::new("watchers").about("Restart the background watcher that takes in email and delivers pending work.")
            )
            .subcommand(Command::new("rotate").about("Replace a manager with a fresh one that takes over its task and reports.")
                .arg(Arg::new("who").required(true).value_name("TASK.md").help("the manager's task file"))
                .arg(Arg::new("tool").long("tool").value_parser(["claude", "codex", "cursor", "antigravity"]).help("default: the same tool"))
                .arg(Arg::new("model").long("model").help("default: the same model"))
                .arg(Arg::new("effort").long("effort").help("default: the same effort"))
            )
            .subcommand(Command::new("worktree").about("List uncommitted changes in manager-owned repositories.")
            )
            .subcommand(Command::new("watch").about("Run the watcher in the foreground; the `amh-watch` service runs this.").long_about("Run the watcher in the foreground; the `amh-watch` service runs this.\n\nScheduled commands in config.toml (machine paths may go in env.toml):\n  [job.cleanup]\n  every = \"1h\"\n  run = \"./cleanup.sh\"\n  dir = \"/path/to/project\"\nUse at = \"04:00\" instead of every for daily local time; or tell = \"TASK\" and text = \"MESSAGE\" instead of run.\n\nStanding agents:\n  [keep.maintenance]\n  dir = \"/path/to/project\"\n  prompt = \"/path/to/goal.txt\"\n  tool = \"codex\"\nA failed, missing or explicitly stopped standing agent restarts after two checks; its task stays long_running. Remove its keep table to stop keeping it alive.\n\nRun `amh manager watchers` to restart the service after installing a new helper. Configuration is reloaded on each poll."))
        )
}
